/**
 * Chinese names (Taiwan medical terminology, 台灣解剖學名詞 conventions: 動脈／靜脈／神經, 橈・尺・脛・腓, 蹠, 旋肱動脈…) for
 * structures that the CMU lecture notes do not name: vessels, digital bones and a few branches. Look-ups take a lower-case
 * English name WITHOUT left/right; the caller adds 左／右.
 *
 * Every entry belongs to one of two tiers:
 *  - standard : the usual Taiwan textbook / 名詞 term.
 *  - check    : a composed or variant term where more than one Taiwan form is in use. They are listed with the reason in
 *               docs/zh-tw-terminology-review.md (generated by scripts/list-zh-review.mjs) for a human to confirm.
 */
import {LOWER_NERVES,THORAX_NERVES,UPPER_NERVES} from './quiz/catalogue';

export interface ZhName {zh:string;check?:string}

