const TOE:Record<string,string>={'big toe':'拇趾','second toe':'第二趾','third toe':'第三趾','fourth toe':'第四趾','little toe':'小趾'};
const SEGMENT:Record<string,string>={proximal:'近節',middle:'中節',distal:'遠節'};
const FINGER_CHECK='指名用語：「無名指」（亦作「環指」）、「拇趾」（亦作「大趾」）與「近節／中節／遠節」（亦作「近端／中間／遠端」）在臺灣並行';

