const NERVE_ZH=new Map<string,string>(Object.entries({...LOWER_NERVES,...UPPER_NERVES,...THORAX_NERVES}).map(([en,v])=>[en,v.zh]));
const NERVE_CHECK:Record<string,string>={
 'posterior antebrachial cutaneous nerve':'亦作「前臂後皮神經」','superior lateral brachial cutaneous nerve':'亦作「臂外側上皮神經」','inferior lateral brachial cutaneous nerve':'亦作「臂外側下皮神經」',
 'medial brachial cutaneous nerve':'亦作「臂內側皮神經」','medial antebrachial cutaneous nerve':'亦作「前臂內側皮神經」','lateral antebrachial cutaneous nerve':'亦作「前臂外側皮神經」',
 'subclavian nerve':'亦作「鎖骨下肌神經」','roots of brachial plexus':'「臂神經叢」與「臂叢」並用','superior trunk of brachial plexus':'「幹」（trunk）','posterior cord of brachial plexus':'「束」（cord）',
 '(communicating branch of median nerve with ulnar nerve)':'組合詞','sympathetic nerves':'泛稱，非單一神經；亦作「交感神經幹」','vagus nerve (x)':'亦作「第十對腦神經」',
 'common palmar digital branches of median nerve':'組合詞','proper palmar digital branches of median nerve':'組合詞','common palmar digital branches of ulnar nerve':'組合詞','proper palmar digital branches of ulnar nerve':'組合詞',
 'dorsal digital branches of radial nerve':'組合詞','dorsal digital branches of ulnar nerve':'組合詞','muscular branches of axillary nerve':'「肌支」','muscular branches of radial nerve':'「肌支」',
 'muscular branches of median nerve':'「肌支」','muscular branches of ulnar nerve':'「肌支」',
};

const bare=(s:string)=>s.toLowerCase().replace(/\s+/g,' ').trim();

/** Digit names, as used in bones and digital vessels. */
function digit(name:string):{zh:string;toe:boolean}|undefined{
 const n=bare(name);
 if(FINGER[n])return{zh:FINGER[n],toe:false};
 if(TOE[n])return{zh:TOE[n],toe:true};
 return undefined;
}

export function zhAnatomy(baseName:string):ZhName|undefined{
 const n=bare(baseName.replace(/\b(?:left|right)\b/gi,' '));
 if(!n)return undefined;
 if(STANDARD[n])return{zh:STANDARD[n]};
 if(CHECK[n])return{zh:CHECK[n][0],check:CHECK[n][1]};
 const nerveKey=n.replace(/\.\d+$/,'');
 if(NERVE_ZH.has(nerveKey))return{zh:NERVE_ZH.get(nerveKey)!,check:NERVE_CHECK[nerveKey]};

 // Phalanges: "distal phalanx of index finger" → 食指遠節指骨 (toes: 趾骨)
 const phalanx=/^(proximal|middle|distal) phalanx of (.+)$/.exec(n);
 if(phalanx){const d=digit(phalanx[2]);if(d)return{zh:d.zh+SEGMENT[phalanx[1]]+(d.toe?'趾骨':'指骨'),check:FINGER_CHECK};}
 // Digital vessels of a named finger
 const proper=/^(?:(lateral|medial) )?proper palmar digital (artery|vein) of (.+)$/.exec(n);
 if(proper){const d=digit(proper[3]);if(d)return{zh:d.zh+(proper[1]?proper[1]==='lateral'?'外側':'內側':'')+'掌側固有指'+(proper[2]==='artery'?'動脈':'靜脈'),check:FINGER_CHECK};}
 // Branches: "<x> branch of <parent artery>" → 〈parent〉〈x〉支
 const branch=/^(.+?) branch(?:es)? of (.+)$/.exec(n);
 if(branch){
  const parent=zhAnatomy(branch[2]);
  const part:Record<string,string>={acromial:'肩峰',deltoid:'三角肌',pectoral:'胸肌',descending:'降',ascending:'升','dorsal carpal':'背側腕'};
  if(parent&&part[branch[1]])return{zh:parent.zh+part[branch[1]]+'支',check:'組合詞'};
 }
 const ordinal=/^(first|second|third|fourth|fifth) (.+)$/.exec(n);
 if(ordinal){const rest=zhAnatomy(ordinal[2]);if(rest)return{zh:ORDINAL[ordinal[1]]+rest.zh,check:rest.check??'序數組合'};}
 return undefined;
}
